<template>
  <div>
    <div class="page-heading"><div><p class="eyebrow">智能比价</p><h1>供应商报价</h1><p>将人工录入、OCR识别和系统接口报价统一为 TOC 成本与综合评分。</p></div><el-button type="primary" @click="openCreate">录入报价</el-button></div>
    <div class="connector-note"><strong>TOC 分析已迁移</strong><router-link to="/material-costs">前往 智能分析 → 物料采购成本分析，查看历史、执行比价及修正成本 →</router-link></div>
    <div class="list-heading"><h2>报价库</h2><p>按页加载历史报价，可编辑服务与交付指标或删除无效报价。</p></div>
    <el-table :data="quotations" class="data-table" empty-text="尚无报价记录"><el-table-column prop="quotation_no" label="报价编号" width="145"/><el-table-column prop="supplier_name" label="供应商" min-width="160"/><el-table-column prop="source_type" label="来源" width="100"/><el-table-column prop="delivery_days" label="交期" width="90"/><el-table-column prop="service_score" label="服务" width="90"/><el-table-column prop="quality_pass_rate" label="成品率" width="100"/><el-table-column label="操作" width="140"><template slot-scope="scope"><el-button type="text" @click="edit(scope.row)">编辑</el-button><el-button type="text" class="danger-link" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table>
    <div class="pagination-row"><span>共 {{ pagination.total }} 条</span><el-pagination background layout="sizes, prev, pager, next" :page-sizes="[10,20,50]" :current-page="pagination.page" :page-size="pagination.page_size" :total="pagination.total" @current-change="changePage" @size-change="changeSize" /></div>
    <el-dialog title="录入供应商报价" :visible.sync="dialogVisible" width="680px"><el-form :model="form" label-width="112px"><el-row :gutter="14"><el-col :span="12"><el-form-item label="供应商名称"><el-input v-model="form.supplier_name" /></el-form-item></el-col><el-col :span="12"><el-form-item label="供应商编码"><el-input v-model="form.supplier_id" /></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="交期（天）"><el-input v-model="form.delivery_days" /></el-form-item></el-col><el-col :span="12"><el-form-item label="报价来源"><el-select v-model="form.source_type" style="width:100%"><el-option label="人工录入" value="manual"/><el-option label="报价单识别" value="ocr"/><el-option label="系统API" value="api"/></el-select></el-form-item></el-col></el-row><el-form-item label="报价单模板"><el-select v-model="form.template_id" clearable placeholder="选择报价单模板" style="width:100%"><el-option v-for="template in quotationTemplates" :key="template.id" :label="`${template.name} v${template.version}`" :value="template.id" /></el-select></el-form-item><el-divider content-position="left">物料与 TOC 要素</el-divider><el-row :gutter="14"><el-col :span="12"><el-form-item label="物料编码"><el-input v-model="form.lines[0].material_code" /></el-form-item></el-col><el-col :span="12"><el-form-item label="物料名称"><el-input v-model="form.lines[0].material_name" /></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="8"><el-form-item label="数量"><el-input v-model="form.lines[0].quantity" /></el-form-item></el-col><el-col :span="8"><el-form-item label="单价"><el-input v-model="form.lines[0].unit_price" /></el-form-item></el-col><el-col :span="8"><el-form-item label="物流成本"><el-input v-model="form.lines[0].logistics_cost" /></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="预期质量损失"><el-input v-model="form.lines[0].expected_quality_loss" /></el-form-item></el-col><el-col :span="12"><el-form-item label="服务/质量分"><div class="inline-fields"><el-input v-model="form.service_score"/><el-input v-model="form.quality_pass_rate"/></div></el-form-item></el-col></el-row></el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存报价</el-button></span></el-dialog>
  </div>
</template>

<script>
import { compareQuotations, createQuotation, deleteQuotation, fetchQuotations, fetchTemplates, linkTemplate, updateQuotation } from "../api/client";

const emptyForm = () => ({ supplier_id: "SUP-", supplier_name: "", currency: "CNY", delivery_days: "14", service_score: "85", quality_pass_rate: "98", source_type: "manual", lines: [{ material_code: "", material_name: "", quantity: "1", unit: "件", unit_price: "0", tax_rate: "0.13", logistics_cost: "0", expected_quality_loss: "0" }] });
export default { data: () => ({ query: { material_code: "", quantity: "1" }, comparison: null, dialogVisible: false, saving: false, comparing: false, form: emptyForm(), quotations: [], quotationTemplates: [], editingId: "", pagination: { page: 1, page_size: 10, total: 0 } }), async created() { await Promise.all([this.load(), this.loadTemplates()]); }, computed: { recommendedName() { return this.comparison.items[0]?.supplier_name || "暂无"; }, maxTco() { return Math.max(...this.comparison.items.map(item => Number(item.tco_amount)), 1); } }, methods: { openCreate() { this.editingId=""; this.form=emptyForm(); this.dialogVisible=true; }, tcoWidth(value) { return `${Math.max(8, Number(value) / this.maxTco * 100)}%`; }, async load() { const result = await fetchQuotations({ page: this.pagination.page, page_size: this.pagination.page_size }); this.quotations = result.items; this.pagination.total = result.total; }, async loadTemplates() { const result = await fetchTemplates({ page: 1, page_size: 100, unfiltered: true }); this.quotationTemplates = result.items.filter(template => template.template_type === "quotation" && template.status === "active"); }, changePage(page) { this.pagination.page = page; this.load(); }, changeSize(size) { this.pagination.page_size = size; this.pagination.page = 1; this.load(); }, edit(quotation) { this.editingId = quotation.id; this.form = { ...quotation, lines: quotation.lines.map(line => ({ ...line })), template_id: quotation.template_id || "" }; this.dialogVisible = true; }, async remove(quotation) { try { await this.$confirm(`确定删除报价 ${quotation.quotation_no} 吗？`, "删除确认", { type: "warning" }); await deleteQuotation(quotation.id); this.$message.success("报价已删除"); await this.load(); } catch (error) { if (error !== "cancel") this.$message.error(error.response?.data?.detail || "报价删除失败"); } }, async compare() { if (!this.query.material_code) return this.$message.warning("请填写物料编码"); this.comparing = true; try { this.comparison = await compareQuotations(this.query); if (!this.comparison.items.length) this.$message.info("没有找到可比较的报价"); } catch (error) { this.$message.error(error.response?.data?.detail || "比价失败"); } finally { this.comparing = false; } }, async save() { this.saving = true; try { let quotation; if (this.editingId) quotation = await updateQuotation(this.editingId, { supplier_id: this.form.supplier_id, supplier_name: this.form.supplier_name, source_type: this.form.source_type, template_id: this.form.template_id || null, lines: this.form.lines, delivery_days: this.form.delivery_days, service_score: this.form.service_score, quality_pass_rate: this.form.quality_pass_rate }); else quotation = await createQuotation(this.form); if (!this.editingId && this.form.template_id) await linkTemplate({ document_type: "quotation", document_id: quotation.id, template_id: this.form.template_id }); this.query.material_code = this.form.lines[0].material_code; this.query.quantity = this.form.lines[0].quantity; this.$message.success(this.editingId ? "报价已更新" : "报价已结构化入库"); this.dialogVisible = false; this.form = emptyForm(); this.editingId = ""; await this.load(); } catch (error) { this.$message.error(error.response?.data?.detail?.[0]?.msg || "报价保存失败"); } finally { this.saving = false; } } } };
</script>
